27→function AnimaDashboard() {
28→  const [mode, setMode] = useState<TriuneMode>("knower");
29→  const [chatOpen, setChatOpen] = useState(false);
30→  const { connected } = useUniverse();
31→
32→  return (
33→    <div className="min-h-screen bg-[var(--background)] text-[var(--foreground)] font-sans relative overflow-hidden">
34→      {/* HIHO CSS Bridge (headless — sets CSS vars from coherence) */}
35→      <HIHOBridge />
36→
37→      {/* Ambient background glow driven by HIHO state */}
38→      <div
39→        className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] blur-[120px] rounded-full pointer-events-none opacity-10"
40→        style={{ backgroundColor: "var(--hiho-glow-color, #00ff00)" }}
41→      />
42→      <div
43→        className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] blur-[150px] rounded-full pointer-events-none opacity-10"
44→        style={{ backgroundColor: "var(--hiho-glow-color, #00ff00)" }}
45→      />
46→
47→      {/* Triune Navigation Header */}
48→      <TriuneNav
49→        activeMode={mode}
50→        onModeChange={setMode}
51→        connected={connected}
52→        onAnimaClick={() => setChatOpen((p) => !p)}
53→      />
54→
55→      {/* Mode Content with ritualized transitions (NFR12) */}
56→      <main className="p-6 lg:p-12 relative z-10 max-w-[1920px] mx-auto pb-20">
57→        <div key={mode} className={MODE_CLASSES[mode]}>
58→          {mode === "knower" && <ObservatoryMode />}
59→          {mode === "thinker" && <VaultMode />}
60→          {mode === "doer" && <CockpitMode />}
61→        </div>
62→      </main>
63→
64→      {/* Anima Chat Panel (slide-out from right, unmounted when closed) */}
65→      {chatOpen && <AnimaChatPanel open={chatOpen} onClose={() => setChatOpen(false)} />}
66→
67→      {/* Anima Narration Bar (Tier 1: template) */}
68→      <AnimaNarrationBar />
69→
70→      {/* Footer */}
71→      <footer className="fixed bottom-12 left-0 right-0 text-center text-[10px] text-gray-600 font-mono z-30">
72→        COHEZION v1.0.2 // TRIUNE SELF // 12D COMPOUND ENGINEERING
73→      </footer>
74→    </div>
75→  );
76→}
