  3→export const HIHOShader = {
  4→    uniforms: {
  5→        uTime: { value: 0 },
  6→        uSize: { value: 25 },
  7→        uBaseColor: { value: new THREE.Color("#00FF88") } // Nexus Green
  8→    },
  9→    vertexShader: `
 10→        uniform float uTime;
 11→        uniform float uSize;
 12→        
 13→        attribute float awareness;
 14→        attribute float stability; // 1.0 - abs(coherence - 0.5) * 2.0
 15→        attribute float novelty;
 16→        attribute float precipitation;
 17→        
 18→        varying float vAwareness;
 19→        varying float vStability;
 20→        varying float vNovelty;
 21→        varying float vPrecipitation;
 22→        varying vec3 vColor;
 23→        varying vec2 vUv;
 24→
 25→        // High-fidelity noise for filament dynamics
 26→        vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
 27→        vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
 28→        vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
 29→        vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }
 30→
 31→        float snoise(vec3 v) {
 32→            const vec2  C = vec2(1.0/6.0, 1.0/3.0);
 33→            const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);
 34→            vec3 i  = floor(v + dot(v, C.yyy));
 35→            vec3 x0 = v - i + dot(i, C.xxx);
 36→            vec3 g = step(x0.yzx, x0.xyz);
 37→            vec3 l = 1.0 - g;
 38→            vec3 i1 = min( g.xyz, l.zxy );
 39→            vec3 i2 = max( g.xyz, l.zxy );
 40→            vec3 x1 = x0 - i1 + C.xxx;
 41→            vec3 x2 = x0 - i2 + C.yyy;
 42→            vec3 x3 = x0 - D.yyy;
 43→            i = mod289(i);
 44→            vec4 p = permute( permute( permute(
 45→                      i.z + vec4(0.0, i1.z, i2.z, 1.0))
 46→                    + i.y + vec4(0.0, i1.y, i2.y, 1.0))
 47→                    + i.x + vec4(0.0, i1.x, i2.x, 1.0));
 48→            float n_ = 0.142857142857;
 49→            vec3 ns = n_ * D.wyz - p.xzw * n_;
 50→            vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
 51→            vec4 x_ = floor(j * ns.z);
 52→            vec4 y_ = floor(j - 7.0 * x_ );
 53→            vec4 x = x_ * ns.x + ns.yyyy;
 54→            vec4 y = y_ * ns.x + ns.yyyy;
 55→            vec4 h = 1.0 - abs(x) - abs(y);
 56→            vec4 b0 = vec4( x.xy, y.xy );
 57→            vec4 b1 = vec4( x.zw, y.zw );
 58→            vec4 s0 = floor(b0)*2.0 + 1.0;
 59→            vec4 s1 = floor(b1)*2.0 + 1.0;
 60→            vec4 sh = -step(h, vec4(0.0));
 61→            vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
 62→            vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
 63→            vec3 p0 = vec3(a0.xy,h.x);
 64→            vec3 p1 = vec3(a0.zw,h.y);
 65→            vec3 p2 = vec3(a1.xy,h.z);
 66→            vec3 p3 = vec3(a1.zw,h.w);
 67→            vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
 68→            p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
 69→            vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
 70→            m = m * m;
 71→            return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3) ) );
 72→        }
 73→
 74→        void main() {
 75→            vAwareness = awareness;
 76→            vStability = stability;
 77→            vNovelty = novelty;
 78→            vPrecipitation = precipitation;
 79→            vUv = uv;
 80→            
 81→            // Filament Perturbation
 82→            vec3 pos = position;
 83→            float noise = snoise(pos * 2.0 + uTime * 0.1);
 84→            pos += normalize(pos) * noise * (1.0 - stability) * 0.5;
 85→
 86→            // Lattice Alignment (Project to 12-sided symmetry)
 87→            float lattice = abs(sin(pos.x * 12.0) * cos(pos.y * 12.0) * sin(pos.z * 12.0));
 88→            pos *= (1.0 + lattice * 0.1 * stability);
 89→
 90→            // Quadrature Geometry proof layer (geometric scaling)
 91→            float quad = 0.0;
 92→            if (stability > 0.8) {
 93→                quad = sin(pos.x * 20.0 + uTime) * sin(pos.y * 20.0) * stability;
 94→                pos += normalize(pos) * quad * 0.02;
 95→            }
 96→
 97→            // Color shift based on Novelty (D11)
 98→            // Range from Nexus Green to Royal Purple
 99→            vec3 lowNovelty = vec3(0.0, 1.0, 0.53); // #00FF88
100→            vec3 highNovelty = vec3(0.5, 0.0, 1.0); // #8000FF
101→            vColor = mix(lowNovelty, highNovelty, novelty);
102→
103→            vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
104→            
105→            // Size scales with Precipitation (D12) and Stability
106→            float s = uSize * (0.5 + precipitation * 1.5) * (0.8 + stability * 0.4);
107→            
108→            gl_PointSize = s * (300.0 / -mvPosition.z);
109→            gl_Position = projectionMatrix * mvPosition;
110→        }
111→    `,
112→    fragmentShader: `
113→        varying float vAwareness;
114→        varying float vStability;
115→        varying float vNovelty;
116→        varying float vPrecipitation;
117→        varying vec3 vColor;
118→        varying vec2 vUv;
119→
120→        void main() {
121→            float dist = distance(gl_PointCoord, vec2(0.5));
122→            if (dist > 0.5) discard;
123→            
124→            // Awareness dictates the core luminosity
125→            // Stability dictates the edge hardness (The 0.5 Rule)
126→            
127→            // Hyper-fidelity crystalline core
128→            float edgeSoftness = 0.45 - (vStability * 0.35); // High stability = sharp edge
129→            float alpha = 1.0 - smoothstep(edgeSoftness, 0.5, dist);
130→            
131→            // Add a "Crystalline" core for high stability
132→            // Additive "lattice" pulse
133→            float latticePulse = sin(vStability * 10.0 + vAwareness * 5.0) * 0.5 + 0.5;
134→            vec3 finalColor = vColor + (vStability * 0.9) + (latticePulse * 0.2);
135→            
136→            // Intensity modulation by Awareness
137→            float intensity = vAwareness * 1.5;
138→            
139→            gl_FragColor = vec4(finalColor * intensity, alpha * vPrecipitation);
140→            
141→            // Glow effect
142→            float glow = (1.0 - dist * 2.0) * 0.5;
143→            gl_FragColor.rgb += vColor * glow * vStability;
144→        }
145→    `
