 1→import init, { DualStateManifold } from '../pkg/cohezion_core_rs';
 2→
 3→const manifolds = new Map<string, DualStateManifold>();
 4→let initialized = false;
 5→
 6→self.onmessage = async (e) => {
 7→    const { type, data } = e.data;
 8→
 9→    switch (type) {
10→        case 'INIT':
11→            if (!initialized) {
12→                await init();
13→                initialized = true;
14→                self.postMessage({ type: 'READY' });
15→            }
16→            break;
17→
18→        case 'HYDRATE':
19→            if (!initialized) return;
20→            // data: { id, latent: float32array }
21→            const { id, latent } = data;
22→            let manifold = manifolds.get(id);
23→            if (!manifold) {
24→                manifold = new DualStateManifold();
25→                manifolds.set(id, manifold);
26→            }
27→            manifold.hydrate(latent);
28→            break;
29→
30→        case 'TICK':
31→            if (!initialized) return;
32→            // data: { dt }
33→            const { dt } = data;
34→            const results: Record<string, { axiomatic: Float32Array; visibility: number }> = {};
35→
36→            manifolds.forEach((manifold, agentId) => {
37→                manifold.evolve_axiomatic(dt);
38→                results[agentId] = {
39→                    axiomatic: manifold.get_axiomatic(),
40→                    visibility: manifold.get_visibility()
41→                };
42→            });
43→
44→            self.postMessage({ type: 'PULSE', results });
45→            break;
46→
47→        case 'TERMINATE':
48→            self.close();
49→            break;
50→    }
51→};
